import{createWebHistory,createRouter}from"vue-router";import store from"@/components/state/store";import rtevitrine from"./rte-vitrine.min.js";import rteerrors from"./rte-errors.min.js";import rtelogin from"./rte-login.min.js";import rtelock from"./rte-lock.min.js";import rteadmin from"./user-specific/rte-admin.min.js";import rteorganisation from"./user-specific/rte-organisation.min.js";import rtemedecin from"./user-specific/rte-medecin.min.js";import rtemedical from"./user-specific/rte-medical.min.js";import rtepatient from"./user-specific/rte-patient.min.js";import rteconfiance from"./user-specific/rte-confiance.min.js";import rteproche from"./user-specific/rte-proche.min.js";import appConfig from"@/../app.config";const router=createRouter({history:createWebHistory(),mode:"history",routes:[...rtevitrine,...rteerrors,...rtelogin,...rtelock,...rteadmin,...rteorganisation,...rtemedecin,...rtemedical,...rtepatient,...rteconfiance,...rteproche],scrollBehavior:(to,from,savedPosition)=>savedPosition||{top:0,left:0}});function rootguard(routeTo,next){"/"===routeTo.path&&(store.getters["auth/getisloggedIn"]?next({path:"/"+store.getters["auth/getuserType"]+"/dashboard"}):next())}router.beforeEach(async(routeTo,routeFrom,next)=>{const authRequired=routeTo.matched.some(route=>route.meta.authRequired);if(!authRequired)return next();store.getters["auth/getisloggedIn"]?next():next({path:"/login"})}),router.beforeResolve(async(routeTo,routeFrom,next)=>{rootguard(routeTo,next);try{for(const route of routeTo.matched)await new Promise((resolve,reject)=>{route.meta&&route.meta.onceLoggedIn?route.meta.onceLoggedIn(routeTo,routeFrom,(...args)=>{args.length?(next(...args),reject(new Error("Redirected"))):resolve()}):resolve()})}catch(error){return}document.title=routeTo.meta.title+" | "+appConfig.title,next()});export default router;